(function(){'use strict';
/* STAGING LOCALE BUILD (cs) — generated by scripts/build_locale_staging.py from assets/growth/tools.js.
 * Only string literals and display formatting differ. Formulas, weights, thresholds, clamping and toFixed() rounding are
 * unchanged; fx() formats the already-rounded value with Intl.NumberFormat. Parity: scripts/locale_tools_parity.js. */
const LOC="cs-CZ";
const fx=(n,d)=>new Intl.NumberFormat(LOC,{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number(n.toFixed(d)));
const PLC=n=>(n===1?"{n} vybraný signál":(n>=2&&n<=4)?"{n} vybrané signály":"{n} vybraných signálů").replace('{n}',String(n));
const VCS_LINK="„{phrase}“ ve VC říká";

const $=id=>document.getElementById(id), num=id=>{const el=$(id);if(!el)return 0;let v=Number(el.value);if(!Number.isFinite(v))return 0;if(el.min!==''&&Number.isFinite(Number(el.min)))v=Math.max(Number(el.min),v);if(el.max!==''&&Number.isFinite(Number(el.max)))v=Math.min(Number(el.max),v);return v};
const money=(n)=>new Intl.NumberFormat(LOC,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number.isFinite(n)?n:0);
const pct=(n)=>fx(Number.isFinite(n)?n:0,1)+'\u00a0%';
function event(name,props={}){try{if(window.posthog&&typeof window.posthog.capture==='function')window.posthog.capture(name,props);if(typeof window.gtag==='function')window.gtag('event',name,props)}catch(e){}}
function bindCalculate(id,fn){const b=$(id);if(!b)return;b.addEventListener('click',()=>{fn();event('tfg_tool_completed',{tool_slug:document.body.dataset.tool||'unknown'})});}
function set(id,value){const el=$(id);if(el)el.textContent=String(value)}
function copyText(txt,button){if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(txt).then(()=>{if(button)button.textContent="Zkopírováno ✓";event('tfg_tool_result_copied',{tool_slug:document.body.dataset.tool||'unknown'})}).catch(()=>fallback())}else fallback();function fallback(){let ta=document.createElement('textarea');ta.value=txt;ta.style.position='fixed';ta.style.top='-9999px';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');if(button)button.textContent="Zkopírováno ✓";event('tfg_tool_result_copied',{tool_slug:document.body.dataset.tool||'unknown'})}catch(e){if(button)button.textContent="Označte text a zkopírujte ho"}ta.remove()}}
const signalItems=[
{key:'next',label:"Navrhne konkrétní další schůzku nebo termín",weight:4,group:'action'},
{key:'partner',label:"Představí vás dalšímu partnerovi nebo člověku, který rozhoduje",weight:4,group:'action'},
{key:'diligence',label:"Vyžádá si konkrétní dokumenty pro due diligence nebo reference zákazníků",weight:3,group:'action'},
{key:'champion',label:"Jasně vysvětlí, jak u nich funguje interní rozhodovací proces",weight:2,group:'action'},
{key:'question',label:"Klade konkrétní doplňující otázky k vašemu byznysu",weight:1,group:'interest'},
{key:'polite',label:"Řekne „zajímavé, dejte nám vědět“ bez dalšího kroku",weight:-2,group:'caution'},
{key:'noresponse',label:"Nedodržel dohodnutý termín odpovědi a neozval se",weight:-2,group:'caution'},
{key:'wrong',label:"Řekne, že fáze, sektor, geografie nebo velikost investice nesedí",weight:-4,group:'caution'},
];
function initSignals(){const wrap=$('signals-list');if(!wrap)return;signalItems.forEach(s=>{let lab=document.createElement('label');lab.className='formcheck';let ch=document.createElement('input');ch.type='checkbox';ch.name='signal';ch.value=s.key;lab.appendChild(ch);lab.append(document.createTextNode(s.label));wrap.appendChild(lab)});bindCalculate('signals-calculate',()=>{const chosen=[...document.querySelectorAll('input[name="signal"]:checked')].map(x=>signalItems.find(s=>s.key===x.value));const score=chosen.reduce((sum,x)=>sum+x.weight,0);const actions=chosen.filter(x=>x.group==='action').length;let status="Nedostatečný signál",desc="Zatím nemáte dost důkazů o konkrétním procesu. Zeptejte se, zda se k investorovi hodíte a jaký bude další rozhodovací bod.",next="Pošlete krátký, konkrétní follow-up s návrhem vhodného dalšího kroku a pokračujte v rozhovorech s dalšími investory.";if(chosen.some(x=>x.key==='wrong')){status="Pravděpodobně strukturální nesoulad";desc="Výslovný nesoulad ve fázi, investiční tezi, geografii nebo velikosti investice má větší váhu než přátelský tón.";next="Poděkujte, zeptejte se, zda neznají vhodnějšího kolegu nebo fond, a vyřaďte příležitost z aktivní pipeline."}else if(score>=5&&actions>=2){status="Významné signály procesu";desc="Několik konkrétních kroků ukazuje na skutečný hodnoticí proces; investici však stále nezaručují.";next="Písemně si potvrďte, kdo za co odpovídá, jaké materiály a termíny platí. Pokračujte i v ostatních rozhovorech."}else if(score>=2&&actions>=1){status="První známky zájmu";desc="Konkrétní krok vypovídá víc než komplimenty, proces ale zatím není průkazný.";next="Splňte, o co vás požádali, a zeptejte se, jaké bude další rozhodnutí a kdy."}else if(score<0){status="Slabá nebo klesající dynamika";desc="Zdvořilý zájem bez činů nebo nedodržené sliby vyžadují vyjasnění, ne optimistický výklad.";next="Pošlete jednu podstatnou novinku a požádejte o jasné ano/ne, zda pokračovat; nevymýšlejte si termíny."}const rel=$('signal-related');if(rel){const has=k=>chosen.some(x=>x.key===k);const id=has('wrong')?'not-right-fit':has('noresponse')?'investor-ghosting':has('partner')?'partner-introduction':has('next')?'second-meeting':has('polite')?'keep-in-touch':null;rel.textContent='';if(id)rel.appendChild(vcSaysLink(id,"Související návod k frázi: "));else{const a=document.createElement('a');a.href="/_staging/locales/cs/vc-says";a.textContent="Prohlédněte si VC říká: běžné fráze investorů a jak na ně odpovědět";rel.appendChild(a)}}set('signal-status',status);set('signal-desc',desc);set('signal-next',next);set('signal-count',PLC(chosen.length));$('signal-meter').style.width=Math.max(5,Math.min(100,(score+8)*5))+'%';});}
function initPipeline(){if(!$('pipeline-calculate'))return;const run=()=>{const leads=num('pipe-leads'), r1=num('pipe-r1')/100,r2=num('pipe-r2')/100,r3=num('pipe-r3')/100,r4=num('pipe-r4')/100;let first=leads*r1,second=first*r2,terms=second*r3,closed=terms*r4;set('pipe-meetings',fx(first,1));set('pipe-deep',fx(second,1));set('pipe-terms',fx(terms,2));set('pipe-closes',fx(closed,2));set('pipe-close-rate',pct(leads>0?closed/leads*100:0));let target=Math.max(.0000001,r1*r2*r3*r4);set('pipe-needed',Math.ceil(1/target).toLocaleString(LOC));set('pipe-note',terms<1?"Při těchto předpokladech se neočekává ani jeden term sheet. Zlepšete shodu s investory, konverze nebo objem oslovení; výsledky nejsou zaručené.":"Jde o model očekávané hodnoty, ne o předpověď skutečných závazků. U malých čísel se výsledky mohou výrazně lišit.");};bindCalculate('pipeline-calculate',run);run();}
function initRunway(){if(!$('runway-calculate'))return;const run=()=>{const cash=num('run-cash'),net=Math.max(0,num('run-expenses')-num('run-revenue')),months=num('run-months'),one=num('run-onetime'),buffer=num('run-buffer')/100,pre=num('run-pre');const core=Math.max(0,net*months+one-cash),raise=core*(1+buffer),post=pre+raise,dil=post>0?raise/post*100:0,existing=net>0?cash/net:Infinity;set('run-net',money(net));set('run-existing',Number.isFinite(existing)?fx(existing,1):"Bez čistého burnu");set('run-raise',money(raise));set('run-dilution',pct(dil));set('run-post',money(post));set('run-pool',money(raise-core));set('run-note',pre<=0?"Pro výpočet zjednodušeného ředění zadejte kladné pre-money ocenění.":"Pouze ilustrativní kolo s pevným oceněním: nezahrnuje opční pool, SAFE, konvertibilní půjčky, poplatky ani změny burnu. Podmínky obchodu si ověřte se svými poradci.");};bindCalculate('runway-calculate',run);run();}
const templates={
 meeting:{subject:"Děkuji za dnešní rozhovor — [Company]",intro:"děkuji za dnešní rozhovor a za váš pohled na [topic].",mid:"Jak jsme se domluvili, pošlu vám [slíbený materiál]. Naše nejdůležitější novinka: [progress].",ask:"Mohli bychom jako další krok naplánovat [specific next step]?"},
 tooearly:{subject:"Re: [Company] — pokrok k milníku",intro:"děkuji za upřímnou zpětnou vazbu, že pro vaše současná investiční kritéria můžeme být zatím v příliš rané fázi.",mid:"Od našeho rozhovoru jsme pokročili takto: [progress]. Soustředím se na milník, o kterém jsme mluvili: [milestone].",ask:"Posunul by nás tento milník blíž k vaší investiční hranici, nebo je tu jiná mezera, kterou bychom měli řešit?"},
 quiet:{subject:"Krátká novinka o [Company]",intro:"navazuji na náš rozhovor na téma [topic].",mid:"Krátká novinka od našeho posledního rozhovoru: [progress].",ask:"Máte ještě zájem v rozhovoru pokračovat, nebo se mám ozvat, až splníme tento milník: [milestone]? Pomůže mi jakákoli odpověď."},
 update:{subject:"[Company] — novinka: [progress]",intro:"ještě jednou děkuji za návrh zůstat v kontaktu po našem rozhovoru na téma [topic].",mid:"Nejdůležitější posun od našeho rozhovoru: [progress]. Dále směřujeme k tomuto milníku: [milestone].",ask:"Bylo by pro vás užitečné zůstat na našem krátkém seznamu investorských novinek, nebo vás zajímá nějaká konkrétní metrika?"},
 notfit:{subject:"Re: [Company] — děkuji",intro:"děkuji za jasnou odpověď — oceňuji, že nemusíme hádat.",mid:"Pokud máte chvilku: šlo hlavně o fázi, sektor, nebo geografii? Pomůže mi to zaměřit se na vhodnější investory.",ask:"Pokud vás napadne fond, který obvykle investuje do firem, jako je ta naše, velmi ocením tip."},
 nolead:{subject:"[Company] — struktura kola",intro:"děkuji za jasnou informaci, že podmínkou je pro vás hlavní investor v kole.",mid:"Nyní se soustředíme na získání hlavního investora. Naše nejdůležitější novinka: [progress].",ask:"Pokud získáme hlavního investora za podmínek v rozsahu, o kterém jsme mluvili, jaká výše investice by pro vás přicházela v úvahu a máte požadavky na to, kdo by měl kolo vést? Velmi ocením i kontakty na fondy, které v naší fázi kola vedou."},
 cold:{subject:"[Company] — krátký follow-up",intro:"navazuji na svou zprávu o [Company], která pomáhá [customer] dosáhnout [outcome].",mid:"Jedna důležitá novinka: [progress].",ask:"Spadá to do vašeho současného investičního zaměření? Pokud vám to pomůže, pošlu stručný přehled."}
};
/* Shared VC Says signal IDs (data/vc_signals.expanded.json). tpl = Follow-up Builder scenario. */
const VC_SAYS={'too-early':{phrase:"Zatím jste pro nás v příliš rané fázi.",tpl:'tooearly'},'not-right-fit':{phrase:"Nezapadá to do naší investiční strategie.",tpl:'notfit'},'keep-in-touch':{phrase:"Zůstaňme v kontaktu.",tpl:'update'},'circle-back-next-quarter':{phrase:"Ozvěte se nám znovu v příštím čtvrtletí.",tpl:'update'},'send-deck':{phrase:"Pošlete mi svou prezentaci pro investory.",tpl:'meeting'},'second-meeting':{phrase:"Domluvme si další schůzku.",tpl:'meeting'},'partner-introduction':{phrase:"Rád bych vás seznámil s kolegou z fondu.",tpl:'meeting'},'need-more-traction':{phrase:"Potřebujeme vidět větší trakci.",tpl:'tooearly'},'no-lead-investor':{phrase:"Ozvěte se, až budete mít hlavního investora.",tpl:'nolead'},'investor-ghosting':{phrase:"Žádná odpověď ani po dvou připomenutích.",tpl:'quiet'}};
function signalFromQuery(){try{const id=new URLSearchParams(location.search).get('signal');return id&&Object.prototype.hasOwnProperty.call(VC_SAYS,id)?id:null}catch(e){return null}}
function vcSaysLink(id,prefix){const p=document.createElement('span');p.append(document.createTextNode(prefix));const a=document.createElement('a');a.href="/_staging/locales/cs/vc-says/"+id;a.textContent=VCS_LINK.replace('{phrase}',VC_SAYS[id].phrase.replace(/[.?!]$/,''));p.appendChild(a);p.append(document.createTextNode('.'));return p}
function clean(str,alt){let x=(str||'').trim().replace(/[\r\n]+/g,' ').slice(0,450);return x||alt}
function initFollowup(){if(!$('followup-calculate'))return;const sig=signalFromQuery();if(sig){const sel=$('follow-type');if(sel&&[...sel.options].some(o=>o.value===VC_SAYS[sig].tpl))sel.value=VC_SAYS[sig].tpl;const note=$('follow-signal-note');if(note){note.textContent='';note.appendChild(vcSaysLink(sig,"Situace je předvyplněna podle záznamu ve VC říká: "));note.hidden=false}event('tfg_followup_signal_prefill',{signal_id:sig})}const run=()=>{const type=$('follow-type').value,t=templates[type],company=clean($('follow-company').value,'[Company]'),person=clean($('follow-name').value,'[Investor name]'),topic=clean($('follow-topic').value,"náš byznys"),progress=clean($('follow-progress').value,"[konkrétní, ověřitelný pokrok]"),milestone=clean($('follow-milestone').value,"[dohodnutý milník]"),next=clean($('follow-next').value,"krátký navazující hovor");let subs={subject:t.subject,intro:t.intro,mid:t.mid,ask:t.ask};for(let k in subs){subs[k]=subs[k].replaceAll('[Company]',company).replaceAll('[topic]',topic).replaceAll('[progress]',progress).replaceAll('[milestone]',milestone).replaceAll('[specific next step]',next)}const out=`Předmět: ${subs.subject}\n\nDobrý den, ${person},\n\n${subs.intro}\n\n${subs.mid}\n\n${subs.ask}\n\nS pozdravem,\n[Your name]`; $('follow-output').value=out;};bindCalculate('followup-calculate',run);$('follow-copy').addEventListener('click',function(){copyText($('follow-output').value,this)});run();}
function init(){initSignals();initPipeline();initRunway();initFollowup();document.querySelectorAll('a[href="/#join"],a[href="/#join"],a.button[href="/"],a[data-signup-cta]').forEach(a=>a.addEventListener('click',()=>event('tfg_signup_cta_clicked',{source_path:location.pathname,tool_slug:document.body.dataset.tool||undefined,article_slug:document.body.dataset.article||undefined})));
if(document.body.dataset.tool){event('tfg_tool_viewed',{tool_slug:document.body.dataset.tool,pathname:location.pathname});}
if(document.body.dataset.article){event('tfg_article_viewed',{article_slug:document.body.dataset.article,pathname:location.pathname});}let tracked=false;const main=document.querySelector('main');if(main)main.addEventListener('input',()=>{if(!tracked&&document.body.dataset.tool){event('tfg_tool_started',{tool_slug:document.body.dataset.tool});tracked=true}},{once:true});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
